  _ = `Совместные наборы`,
  v = `Необязательно: вы можете пригласить других разработчиков, чтобы они включили свои игры в ваш набор. Как владелец набора вы будете отвечать за координацию с ними. Кроме того, как владелец набора только вы сможете опубликовать его в магазине Steam. Приглашённые стороны смогут выбрать, какие игры/комплекты включить в набор. Каждый раз, когда комплект добавляется в набор или изменяется процент скидки, все участники должны будут одобрить включение своей игры в набор, прежде чем он будет опубликован.`,
  y = `Приглашены по коду дружбы`,
  b = `Ограничения видимости`,
  x = `Нет ограничений видимости, связанных с ценами на игры или текущей скидкой. `,
  S = `Возможно, вам понадобится скорректировать цены на игры в определённых валютах или размер скидки, установленной для этого набора.`,
  C = `Вы хотите отменить несохранённые изменения?`,
