  T = `Страницы события распродажи`,
  E = `Здесь вы найдёте страницы распродаж в Steam, где размещена хотя бы одна игра, на которую у вас есть права администратора. В одних случаях эти страницы созданы организаторами событий, в других — Valve (как часть кампании по продвижению).`,
  D = `Это список активных и планируемых страниц распродаж, созданных Valve или одобренной третьей стороной. Чтобы настроить возможность создавать собственные страницы распродаж для нового партнёра, %1$s. Вы также можете отправить новому партнёру %2$s.`,
