  G = `Обзор`,
  K = `Это мероприятие скрыто, и у вас нет права его редактировать. Оно есть у другого члена вашей команды — наведите курсор на иконку группы ниже и нажмите «Посмотреть список участников», чтобы узнать, кто может редактировать мероприятие. Как правило, это пользователи со статусом «Офицер».`,
  q = `Это мероприятие пока не общедоступно, но вы видите его, потому что ваша игра есть на странице распродажи. Если вы считаете, что это ошибка, свяжитесь с организаторами мероприятия.`,
