  it = `Распродажа без фирменной ссылки не будет отображаться в магазине как страница распродажи и не сможет стать избранной, поскольку это делается на основе ссылок.`,
  at = `Создать рапродажу`,
  ot = `Выберите подходящую группу сообщества, в которой хотите создать событие и распродажу`,
  st = `Введите название группы или ссылку на страницу в магазине`,
  ct = `Распродажа должна быть создана на домашней странице создателя (т. е. на странице разработчика, издателя или серии игр). Выполните поиск по названию страницы создателя ниже:`,
  lt = `Введите название группы, связанной со страницей создателя, либо введите ссылку на страницу в магазине, если это предназначается для куратора или недавно созданной группы сообщества.`,
  ut = `1. Выбранный создатель распродажи:`,
  dt = `Удалить создателя и заново выполнить поиск страницы создателя`,
  ft = `2. Убедитесь, что у создателя включена функция партнёрских событий:`,
  pt = `Страницы создателя должна участвовать в бета-тестировании партнёрских событий, чтобы использовать возможности создания распродаж. Это действие необратимо: оно изменит редактор объявлений и не даст создавать связанные объявления. %1$s`,
  mt = `3. Введите минимально необходимую информацию:`,
  ht = `Описательное название события`,
  gt = `Это название мероприятия, которое увидят пользователи. Оно может включать в себя название партнёра и даты проведения`,
  _t = `Фирменная ссылка`,
  vt = `Строка без пробелов, которая появится в адресной строке браузера после /sale/`,
  yt = `Начало распродажи`,
  bt = `Окончание распродажи`,
  xt = `Создать событие!`,
