  qa = `Наша команда определила, что «%1$s» не соответствует условиям участия в мероприятии`,
  Ja = `Игры, приглашённые на официальную тематическую распродажу в Steam, должны точно соответствовать её теме и критериям участия. При отборе мы учитываем такую информацию со страницы игры в магазине, как метки и описанный/показанный игровой процесс.`,
