  Xa = `<2>Обязательные метки в магазине</2>, представляющие тему. Проверить метки, выбранные для вашей игры, вы можете в <1>мастере меток</1>.`,
  Za = `<1>Описание на странице в магазине</1>: мы изучаем трейлер, скриншоты и описание игры, чтобы выяснить, соответствует ли её описание теме мероприятия.`,
