  no = `Запросить проверку для «%1$s»`,
  ro = `Если вы считаете, что ваша игра точно соответствует условиям участия, описанным выше, можете подать обращение. Поскольку при его рассмотрении учитывается только информация со страницы игры в магазине, проверьте её трейлеры, скриншоты и метки ещё раз и убедитесь, что она явно соответствует тематике мероприятия.`,
  io = `Мы рассмотрели обращение по поводу «%1$s» и считаем, что игра не соответствует тематике этого мероприятия. Возможно, её тема и игровой процесс больше подойдут для будущих мероприятий.`,
  ao = `Подать обращение`,
