  co = `Процесс подачи обращения`,
  lo = `Запросы регулярно проверяются как до, так и во время мероприятия «%1$s». Мы сообщим вам о результатах по электронной почте.`,
  uo = `Обращение отклонено`,
  fo = `Наша команда ещё раз проверила вашу игру и определила, что она не может принять участие в событии «%1$s».`,
  po = `Вы можете принимать участие в тематических событиях на протяжении всего года. Ознакомьтесь со списком <1>предстоящих событий</1> или дождитесь мероприятия, тема которого наилучшим образом подойдёт для вашей игры.`,
  mo = `Больше информации здесь: %1$s`,
  ho = `%1$s (документация)`,
  go = `Узнать общую информацию о тематических распродажах в Steam — в том числе подробности о процессе отбора и приглашения, способах участия, видимости и продвижении события, видимости игр-участниц и использовании в маркетинговых материалах — можно в <1>соответствующей документации</1>.`,
  _o = `Нужна помощь?`,
  vo = `Если вы считаете, что ваша игра полностью соответствует правилам участия в этом событии, можете подать обращение.`,
  yo = `Проверьте <1>страницу в магазине</1> и <2>метки</2> своей игры и соотнесите их с условиями участия: мы не рассматриваем такую информацию, как видеоролики с геймплеем, демоверсии или презентации. В процессе проверки мы учитываем только общедоступную информацию.`,
