  Cl = `Ваш продукт будет отображаться на главной странице Steam и страницах соответствующих меток на протяжении 24 часов, а скидка будет действовать от 7 до 14 дней, в зависимости от вашего выбора. Предложение дня начинается в 10:00 по тихоокеанскому времени в указанный день.`,
  wl = `Выбрав доступную дату, вы сможете ввести желаемую скидку и комплекты, участвующие в акции.`,
  Tl = `Просим выбрать размер скидки (в процентах), равный вашему наилучшему предложению в прошлом или превышающий его.`,
  El = `Если вы пока не готовы запланировать «Предложение дня», это можно сделать позже через меню предложений дня. Помните, что у приглашений есть срок действия.`,
  Dl = `%1$s, если вам нужно изменить дату, отменить участие или задать вопрос.`,
  Ol = `Свяжитесь с нами здесь`,
  kl = `Предложения дня: рекомендации`,
  Al = `Мы заметили, что лучше всего, когда игра одновременно представлена в разделе предложение дня, продаётся со скидкой и в ней проходят дополнительные события (например, выпуск обновления, проведение трансляции или событий в сообществе).`,
  jl = `Если вы планируете другие скидки в течение месяца после участия игры в предложении дня, устанавливайте одинаковый размер скидки. Когда мы представляем вашу игру в качестве предложения дня, мы хотим, чтобы это предложение было наилучшим из ранее представленных.`,
  Ml = `Подробнее читайте в <1>документации об акции «Предложение дня»</1>`,
  Nl = `Видимость`,
