  fC = `Базовая цена этого комплекта в одной или нескольких валютах ниже минимально допустимой. Поэтому он не будет доступен для покупки в соответствующих странах, как и везде, где цена со скидкой окажется ниже разрешённого минимума. Чтобы комплект можно было приобрести во всех странах, установите на него цену на уровне минимально допустимой в Steam или выше.`,
