  Tw = `Рекомендуемые цены`,
  Ew = `Чтобы помочь вам управлять ценами в более чем 35 поддерживаемых в Steam валютах, этот инструмент предлагает метод конвертации базовой цены (в долларах США) в подходящие региональные цены. Конвертация основана на комбинации валютного курса, региональной покупательной способности, взимаемых налогах и нашем опыте продаж в конкретных регионах.`,
  Dw = `Кнопка снизу применит сконвертированные цены ко всем видимым комплектам, не считая скрытых при сворачивании строк или фильтрации по тексту.`,
  Ow = `Подробнее о региональном ценообразовании в Steam.`,
