  qT = `На этот комплект в ближайшие 30 дней запланирована скидка. Ваши изменения цен включают в себя повышение в одной или нескольких валютах.`,
  JT = `Ознакомьтесь с <1>правилами установки цен</1>, чтобы получить более детальную информацию о перерывах в установке скидок, возникающих после повышения цен.`,
