  lE = `Ваша текущая цена ниже той, которую обычно можно установить для данной валюты. Вы можете оставить эту цену, но величина возможной скидки будет ограничена, чтобы цена с ней оставалась выше допустимой минимальной суммы транзакции.`,
  uE = `%1$s: цена %3$s (в валюте: %2$s) ниже минимальной (%4$s для этой валюты). Проверьте, нет ли в цене опечатки, например пропущенной цифры. Введите значение %4$s или выше.`,
  dE = `%1$s: цена %3$s (в валюте: %2$s) выше опубликованной (%4$s). Цену периодической подписки нельзя повысить. Введите значение %4$s или ниже. Если вам нужно повысить цену, свяжитесь со службой поддержки Steam.`,
  fE = `Ещё одно изменение цены ниже выходит за пределы диапазона допустимых значений.`,
  pE = `Другие изменения цены ниже (%1$s) выходят за пределы диапазона допустимых значений.`,
  mE = `Эти цены нельзя отправить на проверку, пока не будут решены указанные проблемы. Подробную информацию можно найти в <1>документации о ценообразовании</1>.`,
  hE = `Учитывая выбранный метод конвертации и цену в долларах США, введённая цена гораздо выше рекомендованной (%1$s).`,
  gE = `Учитывая выбранный метод конвертации и цену в долларах США, введённая цена гораздо ниже рекомендованной (%1$s).`,
  _E = `Учитывая выбранный метод конвертации и цену в долларах США, введённая цена гораздо ниже рекомендованной (%1$s). При такой цене нельзя будет установить скидку больше %2$s%, так как иначе цена со скидкой составит меньше 49 центов США.`,
