  OO = `Использование: вертикальное изображение «В центре внимания» показывается в разделе «Скидки и мероприятия» на главной странице. Данное изображение требуется только для распродаж серий игр и распродаж от издателя. В разделах «В центре внимания», включающих только одну игру, будет автоматически использоваться её вертикальное изображение для магазина.`,
  kO = `Дизайн: изображения «В центре внимания» должны быть такого же размера, как вертикальные изображения игры.`,
  AO = `На изображении «В центре внимания» должны быть только иллюстрация и логотип вашей игры`,
