  WO = `Логотип: можно использовать основной логотип игры или официальный логотип обновления, если он есть. При наличии предоставьте отдельные версии логотипа на разных языках.`,
  GO = `Не добавляйте дополнительный текст на изображение. Информация об обновлении и призыв к действию будут показаны рядом с изображением автоматически.`,
