  QO = `Требуется два формата: крупный и для мобильных устройств. Для предпросмотра достаточно загрузить статичные версии верхнего баннера, даже если вы планируете использовать анимированные.`,
  $O = `Размер файла — менее 5 Мбайт, допустимые форматы — JPG, GIF, PNG`,
