  dk = `Дизайн: левый, правый и нижний края должны становиться прозрачными или переходить в однотонный фон, совпадающий с фоновым цветом страницы. Подробности можно найти в файле шаблона. Если вы не используете логотип для страницы распродажи, то в безопасной зоне вверху этого изображения следует разместить логотип и даты события.`,
