  _k = `Применение: используется при показе вашего мероприятия в новостном центре Steam и на странице специальных предложений, а также отображается в превью, когда пользователи делятся ссылкой на мероприятие в соцсетях.`,
  vk = `Дизайн: на этом изображении должны быть логотип и даты мероприятия`,
  yk = `Верхнее изображение для распродажи`,
  bk = `Применение: это изображение показывается вверху объявления, связанного со страницей распродажи.`,
  xk = `Дизайн: это изображение необязательно; его можно использовать, чтобы добавить контекста и живости текстовому объявлению.`,
  Sk = `Изображение должно быть статичным, размер файла —\xA0менее 5 Мбайт, допустимые форматы — JPG, PNG`,
