  wk = `Применение: этот баннер отображается над каждой игрой, участвующей в мероприятии. Чтобы использовать эту функцию, необходимо получить разрешение от создателей всех участвующих игр.`,
  Tk = `Дизайн: на этом изображении должны быть логотип и даты мероприятия, а также желательно призыв к действию или краткий слоган мероприятия, чтобы игроки могли понять контекст.`,
  Ek = `Изображение должно быть статичным, размер файла —\xA0менее 5 Мбайт, допустимые форматы — JPG, PNG`,
