  Rk = `Заполните обязательное поле, чтобы отправить запрос на изображение.`,
  zk = `Заканчивается %1$s`,
  Bk = `Важно! Требования к материалам`,
  Vk = `Взгляните на контрольный список ниже и отправьте нам все необходимые изображения, чтобы мы перевели это предложение на все языки, поддерживающиеся в Steam!`,
  Hk = `Размер отдельного файла не должен превышать 5 Мбайт`,
  Uk = `Иллюстрации должны быть файлами PSD с разделением на слои`,
  Wk = `Основные иллюстрации игры/персонажей (предпочтительно смарт-объекты) должны быть в максимально высоком разрешении. Это позволит нам использовать их повторно для создания рекламных изображений в случае необходимости.`,
  Gk = `Логотип (предпочтительно смарт-объект), отделённый от изображения.`,
  Kk = `Весь текст должен быть редактируемым и находиться в отдельной папке «text» в документе .psd, чтобы наша команда могла его локализовать.`,
  qk = `Отправьте все используемые шрифты (особенно нестандартные).`,
  Jk = `Храните все стили текста и слои в Photoshop. Не используйте связанные файлы из других программ, например Illustrator.`,
  Yk = `Анимированные материалы должны быть идеально закольцованы, иметь формат MP4 или PNG и не содержать текста и логотипов. Текст должен находиться в отдельном слое и быть статичным, чтобы наша команда могла его локализовать.`,
  Xk = `Подробную информацию и примеры, а также требования к анимированным изображениям можно найти в <1>документации</1>.`,
  Zk = `Сообщение от представителя Steam`,
  Qk = `Контрольный список изображений`,
  $k = `Загрузить вертикальное изображение «В центре внимания» для предварительного просмотра`,
  eA = `Загрузив файлы ниже, вы сможете проверить изображения и убедиться, что они соответствуют размеру и структуре наших шаблонов.`,
  tA = `Изображения для маркетингового сообщения не требуются`,
  nA = `В маркетинговом сообщении будут использоваться существующие скриншоты, трейлер и основное изображение, которые отображаются на странице вашей игры в магазине.`,
  rA = `Предпросмотр: загрузите маркетинговое сообщение`,
  iA = `Предпросмотр: загрузите изображения для приложения промоакции`,
  aA = `Загрузив файлы ниже, вы сможете проверить изображения и убедиться, что они соответствуют размеру и структуре наших шаблонов.`,
  oA = `Предпросмотр: загрузите верхний баннер`,
  sA = `Ниже вы можете загрузить для предпросмотра файлы верхнего баннера, а также его версии для мобильных устройств и убедиться, что они соответствуют размеру и структуре наших шаблонов.`,
  cA = `Предпросмотр: загрузите нижний баннер`,
  lA = `Ниже вы можете загрузить для предпросмотра файлы нижнего баннера, а также его версии для мобильных устройств и убедиться, что они соответствуют размеру и структуре наших шаблонов.`,
  uA = `Предпросмотр: загрузите изображение для страницы распродажи`,
  dA = `Ниже вы можете загрузить для локализации предварительные версии пяти изображений, которые будут использоваться на странице распродажи. Убедитесь, что они соответствуют размеру и структуре наших шаблонов.`,
  fA = `Особые инструкции`,
  pA = `Оставьте особые инструкции или дополнительную информацию о своих материалах для представителя Steam. К примеру, можете упомянуть, что вы включили информацию о грядущем обновлении, или сообщить о специальных требованиях к использованию фирменного стиля на ваших изображениях.`,
