  Bj = `Ближайшая возможная дата выхода: %1$s`,
  Vj = `Продукт можно выпустить, только если он находится в разделе «Скоро выйдет» не менее двух недель или если с уплаты взноса за него прошёл 21 день. Учтите это при выборе даты выпуска.`,
  Hj = `Продукт можно выпустить, только если он находится в разделе «Скоро выйдет» не менее двух недель. Учтите это при выборе даты выпуска.`,
  Uj = `Укажите дату, когда вы планируете выпустить своё приложение в Steam. Если до выпуска ещё далеко, укажите ориентировочное число. Если вам необходимо отложить выпуск, новую дату нужно ввести не менее чем за две недели до указанной ранее даты.`,
