  Gj = `Указанное время — тихоокеанское.`,
  Kj = `Текущая предполагаемая дата выпуска — %1$s. Если вы хотите изменить её, пожалуйста, <1>свяжитесь с Valve здесь,</1> указав новую дату и причину изменения. Постарайтесь выбрать такую дату, которую не понадобится изменять вновь.`,
  qj = `ПРИМЕЧАНИЕ: поскольку страница о скором выпуске уже опубликована, то, изменив дату выхода здесь, вы измените её и в магазине. Также опубликуются все текущие изменения страницы.`,
  Jj = `ПРИМЕЧАНИЕ: самая ранняя из возможных дат выпуска — %1$s. Вы сможете выпустить продукт в любой момент после этой даты вне зависимости от установленной предполагаемой даты выпуска.`,
