  eM = `Публично отображаемая дата`,
  tM = `Используйте эту опцию, чтобы определить, как дата будет отображаться в магазине.`,
  nM = `Если выбрать общий формат, например месяц и год или год, при сортировке ваша игра окажется в конце списка на указанный период времени.`,
