  dM = `Письма о демоверсии в списке желаемого`,
  fM = `Опция доступна в течение 14 дней после выпуска`,
  pM = `Документация о списках желаемого`,
  mM = `Когда вы впервые выпускаете демоверсию, то можете попросить Steam уведомить об этом всех пользователей, добавивших основную игру в желаемое. Эта возможность предоставляется лишь один раз в течение двух недель после выпуска демоверсии. Сделать другую рассылку нельзя в течение следующих двух недель, поэтому, если вы планируете выпустить игру в течение двух недель, мы рекомендуем сохранить эту возможность для основной игры.`,
  hM = `Ваша основная игра выйдет через две недели — %1$s. Если вы сейчас отправите эл. письма пользователям, добавившим игру в желаемое, вы не сможете отправить им уведомления по случаю выхода полной версии!`,
  gM = `%1$s вы отправили письма пользователям, добавившим игру в желаемое. Для доставки всех писем может потребоваться некоторое время.`,
  _M = `Открыть статистику по спискам желаемого`,
  vM = `(Это предупреждение исчезнет после %1$s.)`,
  yM = `Отправить эл. письма добавившим игру в желаемое`,
  bM = `Письма о демоверсиях в списках желаемого отправлены!`,
  xM = `При отправке писем о списках желаемого произошла ошибка. Повторите попытку позже.`,
  SM = `При получении информации о вашей демоверсии произошла ошибка. Повторите попытку позже.`,
  CM = `Для вашей основной игры и демоверсии действуют разные региональные ограничения. Для обоих продуктов должны действовать одни и те же списки разрешённых и запрещённых стран. Основная игра %1$s. Демоверсия %2$s.`,
  wM = `Для вашей основной игры и демоверсии действуют разные региональные ограничения. Эл. письма о продуктах из списка желаемого будут отправлены только тем пользователям, у которых есть доступ к обоим товарам. Основная игра %1$s. Демоверсия %2$s.`,
  TM = `доступна только в следующих регионах: %1$s`,
  EM = `недоступна в следующих регионах: %1$s`,
  DM = `не имеет ограничений`,
  OM = `Внимание! Ваша демоверсия пока не отображается в магазине:`,
  kM = `Привяжите демоверсию к основной игре здесь: <1>«Изменить страницу в магазине» > «Особые настройки» > «Привязанные демоверсии»</1>. Затем опубликуйте изменения. Применение этих обновлений может занять несколько минут.`,
  AM = `Отправить эл. письма о выходе демоверсии добавившим игру в желаемое?`,
  jM = `Отправить электронные письма о выходе демоверсии всем пользователям, добавившим игру в список желаемого?`,
  MM = `Важные ограничения`,
  NM = `<1><2>Сделать рассылку о выходе определённой демоверсии можно только один раз.</2> Даже если вы отключите демоверсию и включите её вновь, разослать уведомления будет нельзя.</1><1><2>Steam не отправляет письма об игре одному и тому же пользователю чаще, чем раз в две недели</2> Если вы выпустите полную версию игры в течение двух недель после этой рассылки, Steam не отправит электронные письма с уведомлением тем, кто получит их сегодня. Учитывайте это при планировании.</1>`,
  PM = `Отправить письма`,
  FM = `Отмена`,
  IM = `Если ваша игра скоро выходит, используйте эту опцию, чтобы выбрать, как будет выглядеть желаемый выпуск в магазине.`,
