  GM = `Чтобы как можно лучше описать уровень поддержки контроллеров в вашей игре, запустите наш мастер и ответьте на несколько вопросов.

Сообщите нам всё, что знаете о поддержке контроллеров в своей игре, чтобы Steam мог предложить её владельцам тех или иных устройств.`,
  KM = `Состояние: мастер не запущен`,
  qM = `Состояние: контроллеры не поддерживаются`,
  JM = `Запустить мастер`,
  YM = `Основываясь на ваших ответах про поддержку контроллеров, Steam покажет пользователям следующее:`,
  XM = `Примечание: информация о поддержке контроллеров не появится в библиотеке Steam до публикации страницы в магазине.`,
