  fI = `Как вы планируете использовать ключи:`,
  pI = `Запрос ключей`,
  mI = `Результаты`,
  hI = `За последний месяц`,
  gI = `За последнюю неделю`,
  _I = `За последние 90 дней`,
  vI = `Подробная информация`,
  yI = `Дата: %1$s`,
  bI = `%1$s: %2$s (%3$s%)`,
  xI = `Все остальные приложения:`,
  SI = `Всего:`,
  CI = `ВАЛОВАЯ ВЫРУЧКА`,
  wI = `КОПИИ В STEAM`,
  TI = `ДОБАВЛЕНИЯ В ЖЕЛАЕМОЕ`,
  EI = `Введите текст`,
