  FI = `Ваши демоверсии, которые были представлены на мероприятии.`,
  II = `Всего игроков`,
  LI = `Число уникальных игроков, сыгравших в вашу демоверсию во время мероприятия.`,
  RI = `Всего добавлений в желаемое`,
  zI = `Число новых добавлений вашей игры в списки желаемого во время мероприятия.`,
  BI = `Сыгравших и добавивших в желаемое`,
  VI = `Включает игры, которые игроки и запустили, и добавили в список желаемого во время мероприятия. Такие игры также учитываются в статистике по общему числу игроков и добавлений в желаемое.`,
  HI = `Приложения с демоверсиями`,
  UI = `Всего сыгравших`,
  WI = `Всего добавлений в желаемое`,
  GI = `Сыгравших и добавивших в желаемое`,
  KI = `Посещения страницы в магазине (переходы со страницы фестиваля)`,
  qI = `Все посещения страницы вашей игры в магазине при переходе по ссылке со страницы фестиваля «Играм быть» во время мероприятия. Показаны только для игр, у которых вы можете просматривать данные маркетингового трафика.`,
  JI = `Посещения страницы в магазине во время фестиваля`,
  YI = `Все посещения страницы вашей игры в магазине во время мероприятия (из любого места Steam или интернета). Показаны только для игр, у которых вы можете просматривать данные маркетингового трафика.`,
