  QI = `Нет доступа к финансовой информации для этого приложения`,
  $I = `Загрузка приложения (%1$s)`,
  eL = `Подробнее об управлении аккаунтом Steamworks можно прочитать в документации.`,
  tL = `Фестиваль «Играм быть»`,
  nL = `Подробнее о фестивале «Играм быть» читайте в его документации:`,
  rL = `Документация фестиваля «Играм быть»`,
  iL = `У вас нет игр, которые были недавно представлены на фестивале «Играм быть».`,
  aL = `Ваши итоги`,
  oL = `Нажмите на фестиваль «Играм быть» ниже, чтобы подробнее узнать, как он прошёл для ваших игр`,
  sL = `Ваши игры:`,
  cL = `Больше продуктов (от разработчика / от издателя / из серии игр)`,
  lL = `Для вашего приложения не настроено ни одной страницы создателя. Ознакомьтесь с документацией о <1>страницах разработчиков, издателей</1> и <2>серий игр</2>, чтобы создать их для своего приложения.`,
  uL = `Выберите связанную домашнюю страницу создателя, товары с которой будут отображаться на странице игры в магазине. Этот раздел появится под описанием вашей игры.`,
  dL = `Выбранная страница:`,
  fL = `Выбранный источник:`,
  pL = `Сортировать по:`,
