  lV = `введите уникальный идентификатор...`,
  uV = `Используется вызовами API. Минимальная длина —\xA03 символа, максимальная — %1$s. Буквенно-цифровой формат в нижнем регистре без пробелов. Можно использовать знаки «_» и «-».`,
  dV = `Идентификатор содержит неподдерживаемые символы. Необходимо использовать буквенно-цифровой формат в нижнем регистре без пробелов. Можно использовать знаки «_» и «-». Минимальная длина —\xA03 символа.`,
  fV = `Идентификатор не должен начинаться со слова steam_, так как оно зарезервировано для официальных иконок.`,
  pV = `Для каждой иконки загрузите файл формата PNG или SVG и присвойте уникальный идентификатор, который будет использоваться при вызовах API.`,
  mV = `Иконка (файл формата SVG или PNG)`,
  hV = `Иконки формата SVG будут отображаться в размере 36 на 36 пикселей. Пожалуйста, создайте файл соответствующего размера. Изображения формата PNG должны быть квадратными с размером сторон от 24 до 256 пикселей.`,
  gV = `Иконки формата SVG будут отображаться в размере 36 на 36 пикселей. Пожалуйста, создайте файл соответствующего размера. Изображения формата PNG должны быть квадратными с размером сторон от 24 до 256 пикселей.`,
