  yH = `Копия отметки создана. `,
  bH = `Вы можете выбрать одну или несколько веток, с которыми хотите связать эти элементы. Они будут доступны всем игрокам при запуске соответствующих веток. Если выбранная ветка не защищена паролем, мы будем расценивать иконки как общедоступные.`,
  xH = `В список веток изменений не вносилось`,
  SH = `В список веток были внесены изменения. Добавлены названия веток (%1$s шт.). Удалены названия веток (%2$s шт.).`,
  CH = `Эта ветка защищена паролем.`,
  wH = `Создать новый набор веток`,
  TH = `Изменить набор веток`,
  EH = `Название набора веток (для внутреннего использования)`,
