  VH = `Приведённые выше наборы веток и общедоступные иконки могут задавать определённые отметки на временной шкале для следующих веток. Если в наборе веток нет опубликованных иконок, то его данные не учитываются:`,
  HH = `У этих наборов веток нет собственных опубликованных файлов. При использовании этих веток будут применяться стандартные отметки на временной шкале.`,
