  WH = `Достижения`,
  GH = `%1$s%`,
  KH = `Наборы достижений`,
  qH = `Используйте наборы, чтобы управлять ограничениями доступа к достижениям и их видимостью. Например, вы можете создать набор достижений, доступный только владельцам определённого дополнения.`,
