  $H = `Определите и обновите достижения для своей игры.`,
  eU = `Для иконок достижений лучше всего использовать PNG-файлы 256 на 256 пикселей. Они могут быть и меньше (64 на 64 пикселя), но больший размер предпочтителен. Мы также рекомендуем использовать цветные иконки для полученных достижений, а для неполученных — чёрно-белые.`,
  tU = `Поскольку достижения могут отображаться в разных местах сообщества Steam, их названия и иконки должны подходить любой возрастной группе и аудитории. Valve может полностью удалить игру из магазина, если её достижения нарушают <1>рекомендации по поведению и контенту</1> или являются оскорбительными.`,
  nU = `Чтобы включить полноценное использование достижений и завершить контрольный список для выпуска, поставьте отметку об их наличии в разделе <1>«Поддерживаемые функции»</1> при изменении страницы в магазине.`,
  rU = `Перед выпуском <1>вы можете просмотреть свои достижения здесь</1>. Для каждого из них будет отображаться статус выпуска.`,
