  OG = `Сюда можно загрузить только один файл.`,
  kG = `Массовый импорт`,
  AG = `CSV-файлы для определений достижений и локализации. Используйте кнопки справа, чтобы скачать их шаблоны. Примечания в скобках в строке заголовка — это инструкции, которые игнорируются при загрузке файла.`,
  jG = `PNG-файлы для иконок достижений. Используйте в названиях файлов изображений названия достижений для API и суффикс _ACHIEVED или _UNACHIEVED. Например: LEVEL_20_ACHIEVED.png.`,
